  67	const sdkProperty = (value: unknown, key: PropertyKey): unknown => {
  68	  if (typeof value !== "object" || value === null) {
  69	    return null;
  70	  }
  71	  const descriptor = Option.liftThrowable(Object.getOwnPropertyDescriptor)(
  72	    value,
  73	    key
  74	  );
  75	  return Option.match(descriptor, {
  76	    onNone: () => null,
  77	    onSome: (property) => {
  78	      if (property === undefined || !("value" in property)) {
  79	        return null;
  80	      }
  81	      const propertyValue: unknown = property.value;
  82	      return propertyValue;
  83	    },
  84	  });
  85	};
