  87	const makeSdkObservedFailure = (
  88	  operation: PhotonSdkOperation,
  89	  phase: PhotonSdkPhase,
  90	  failure: unknown
  91	) => {
  92	  const nestedCause = sdkProperty(failure, "cause");
  93	  const transportStatus = sdkProperty(nestedCause, "code");
  94	  const retryable = sdkProperty(failure, "retryable");
  95	  return new PhotonSdkObservedFailure({
  96	    operation,
  97	    phase,
  98	    transportStatus:
  99	      typeof transportStatus === "number" &&
 100	      Number.isSafeInteger(transportStatus) &&
 101	      transportStatus >= 100 &&
 102	      transportStatus <= 599
 103	        ? transportStatus
 104	        : "unknown",
 105	    retryable: typeof retryable === "boolean" ? retryable : "unknown",
 106	  });
 107	};
